import {today,shift,days,uid,emptyData,demoData,validateData,health,impacts,projectsCSV,milestoneDate,dependencyRisks,MAX_BACKUP_BYTES,backupJSON,filterProjects,filterOrganization,filterDependencies,weekBounds,weeklyDeliveries,filterMilestones,isDate} from './core.js';
const $=id=>document.getElementById(id), KEY='orbita-pmo-v1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=d=>d?new Date(d+'T12:00:00').toLocaleDateString('pt-BR'):'—';
let timelineView='projects',timelineSort='forecast',selectedWeek=weekBounds(today()).start,weeklyGroup='squad',organizationSearch='',projectSearch='';
let data,storageBlocked=false,corruptRaw=null,currentView='dashboard',editing=null,toastTimer;
try{const raw=localStorage.getItem(KEY);data=raw?validateData(JSON.parse(raw)):demoData();}catch(e){data=emptyData();storageBlocked=true;try{corruptRaw=localStorage.getItem(KEY);}catch{};}
function toast(message){$('toast').textContent=message;$('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('visible'),6500);}
function save(candidate){const valid=validateData(candidate);backupJSON(valid);if(storageBlocked)throw Error('O armazenamento precisa ser recuperado. Exporte seus dados e use “Reativar armazenamento”.');try{localStorage.setItem(KEY,JSON.stringify(valid));}catch{throw Error('Não foi possível salvar. Verifique o espaço e as permissões do navegador. Os dados atuais foram preservados.');}data=valid;$('save-state').textContent='Salvo neste navegador';render();}
function clone(){return structuredClone(data);}
function download(text,name,type){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function currentFilters() {
  return { search: $('search').value, clusterId: $('cluster-filter').value,
    squadId: $('squad-filter').value, status: $('status-filter').value };
}
function selected() {
  const filters = currentFilters();
  if (currentView === 'organization') {
    const visible = filterOrganization(data, filters);
    const squads = new Set(visible.flatMap(cluster => cluster.squads.map(squad => squad.id)));
    return data.projects.filter(project => squads.has(project.squadId));
  }
  return filterProjects(data, filters);
}
const by=(kind,id)=>data[kind].find(x=>x.id===id),name=(kind,id)=>by(kind,id)?.name||'—';
function optionList(rows,selectedId,placeholder){return `<option value="">${esc(placeholder||'Selecione')}</option>`+rows.map(x=>`<option value="${esc(x.id)}" ${x.id===selectedId?'selected':''}>${esc(x.name)}</option>`).join('');}
function setFilters() {
  const cluster = $('cluster-filter').value, squad = $('squad-filter').value;
  $('cluster-filter').innerHTML = optionList(data.clusters, cluster, 'Todos os clusters');
  const rows = data.squads.filter(item => !$('cluster-filter').value || item.clusterId === $('cluster-filter').value);
  $('squad-filter').innerHTML = optionList(rows, squad, 'Todas as squads');
}
function badge(p){const h=health(data,p);return `<span class="badge ${h.tone}">${esc(h.label)}</span>`;}
function pTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Projeto / Squad</th><th>Saúde</th><th>Previsão final</th><th>Responsável</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><button class="project-name" data-edit="projects" data-id="${esc(p.id)}"><span class="row-dot ${health(data,p).tone}"></span>${esc(p.name)}</button><span class="subtext">${esc(name('clusters',p.clusterId))} / ${esc(name('squads',p.squadId))}</span></td><td>${badge(p)}</td><td>${fmt(p.forecast||p.end)}<span class="subtext">Planejado: ${fmt(p.end)}</span></td><td>${esc(p.owner)}<span class="subtext">${esc(p.priority)} prioridade</span></td><td><button class="quiet" data-detail="${esc(p.id)}">Detalhes →</button></td></tr>`).join('')}</tbody></table></div>`:empty('Nenhum projeto por aqui','Cadastre um projeto ou ajuste os filtros.');}
function empty(title,body){return `<div class="empty"><strong>${esc(title)}</strong>${esc(body)}</div>`;}
function milestones(rows){return rows.length?rows.map(m=>{const p=by('projects',m.projectId),dt=new Date(milestoneDate(m)+'T12:00:00');return `<div class="milestone-row"><div class="date-tile">${dt.toLocaleDateString('pt-BR',{month:'short'}).replace('.','')}<b>${dt.getDate()}</b></div><div><button type="button" class="project-name" data-edit="milestones" data-id="${esc(m.id)}">${esc(m.name)}</button><span class="subtext">${esc(p?.name)} ${m.done?'· Concluído':''}</span></div><button type="button" class="quiet" data-edit="milestones" data-id="${esc(m.id)}">Editar</button></div>`;}).join(''):empty('Sem marcos neste período','Cadastre entregas para acompanhar as datas.');}
function getAlerts(ps){const ids=new Set(ps.map(p=>p.id)),alerts=[];for(const p of ps){const h=health(data,p);if(h.tone==='danger')alerts.push({title:p.name,text:'Prazo previsto vencido. Revise as entregas e os impactos.',tone:'danger',id:p.id});if(p.status!=='Concluído'&&days(p.updated,today())>7)alerts.push({title:'Atualização pendente',text:p.name+' · há '+days(p.updated,today())+' dias sem atualização.',tone:'warning',id:p.id});if(!data.milestones.some(m=>m.projectId===p.id))alerts.push({title:'Projeto sem marcos',text:p.name+' · cadastre entregas para avaliar os riscos.',tone:'warning',id:p.id});}for(const risk of dependencyRisks(data)){const source=by('milestones',risk.source),supplier=by('projects',source.projectId);const affectedProjects=[...new Set(risk.affected.map(id=>by('milestones',id)?.projectId))];for(const pid of affectedProjects){if(!ids.has(pid))continue;alerts.push({title:'Impacto potencial na cadeia',text:source.name+' · '+supplier.name+' ('+name('clusters',supplier.clusterId)+' / '+name('squads',supplier.squadId)+') pode afetar '+name('projects',pid)+'.',tone:'warning',id:pid});}}return alerts;}
function dashboard(ps){const hs=ps.map(p=>health(data,p)),n=tone=>hs.filter(h=>h.tone===tone).length;const ms=data.milestones.filter(m=>ps.some(p=>p.id===m.projectId)&&!m.done).sort((a,b)=>milestoneDate(a).localeCompare(milestoneDate(b)));const alerts=getAlerts(ps);return `<section class="metrics" aria-label="Indicadores do portfólio"><article class="metric"><span class="metric-icon">▦</span><span class="metric-label">Projetos no portfólio</span><b class="metric-value">${ps.length.toString().padStart(2,'0')}</b><span class="metric-foot">${ps.filter(p=>p.status==='Em andamento').length} em andamento · visão filtrada</span></article><article class="metric success"><span class="metric-icon">✓</span><span class="metric-label">No prazo</span><b class="metric-value">${n('success').toString().padStart(2,'0')}</b><span class="metric-foot">Entregas com marcos cadastrados</span></article><article class="metric warning"><span class="metric-icon">!</span><span class="metric-label">Em atenção</span><b class="metric-value">${n('warning').toString().padStart(2,'0')}</b><span class="metric-foot">Replanejamento ou dependência</span></article><article class="metric danger"><span class="metric-icon">◷</span><span class="metric-label">Atrasados</span><b class="metric-value">${n('danger').toString().padStart(2,'0')}</b><span class="metric-foot">Previsão de entrega vencida</span></article></section><div class="grid-main"><div><section class="card"><div class="card-head"><div><h2>Saúde do portfólio</h2><p>Acompanhe a execução e antecipe o próximo movimento.</p></div><button class="quiet" data-go="projects">Ver todos →</button></div><div class="card-body"><div class="mini-chart" aria-label="Distribuição da saúde">${['success','warning','danger','neutral'].map(t=>`<span class="${t}" style="flex:${n(t)}"></span>`).join('')}</div><div class="legend"><span><i class="dot success"></i>No prazo ${n('success')}</span><span><i class="dot warning"></i>Atenção ${n('warning')}</span><span><i class="dot danger"></i>Atrasado ${n('danger')}</span><span><i class="dot neutral"></i>Outros ${n('neutral')}</span></div></div>${pTable(ps.slice(0,6))}</section><section class="card"><div class="card-head"><div><h2>Distribuição por cluster</h2><p>Projetos no recorte selecionado.</p></div><span class="badge">${data.clusters.length} clusters</span></div><div class="card-body">${data.clusters.length?data.clusters.map(c=>{const num=ps.filter(p=>p.clusterId===c.id).length;return `<div class="cluster-row"><strong>${esc(c.name)}</strong><div class="cluster-track"><span style="width:${ps.length?num/ps.length*100:0}%"></span></div><small>${num}</small></div>`;}).join(''):empty('Estruture sua tribo','Cadastre clusters e squads para começar.')}</div></section></div><div><section class="card"><div class="card-head"><div><h2>Pontos de atenção <small>${alerts.length}</small></h2><p>O que merece sua próxima decisão. Atualização pendente: mais de 7 dias.</p></div><span class="badge warning">Radar</span></div><div class="card-body">${alerts.length?alerts.slice(0,5).map(a=>`<article class="alert-item ${a.tone}"><strong>${esc(a.title)}</strong><p>${esc(a.text)}</p><button data-detail="${esc(a.id)}">Abrir projeto →</button></article>`).join(''):empty('Nenhum alerta no recorte','Continue atualizando as previsões e dependências.')}${alerts.length>5?`<p class="subtext">Mais ${alerts.length-5} alertas. Consulte os projetos.</p>`:''}</div></section><section class="card"><div class="card-head"><div><h2>Próximas entregas</h2><p>Marcos pendentes por previsão de data.</p></div><button class="quiet" data-go="timeline">Ver agenda →</button></div><div class="card-body">${milestones(ms.slice(0,4))}</div></section>${weeklyCard(ps)}</div></div>`;}
function projectTimeline(ps){if(!ps.length)return empty('Sem projetos no cronograma','Cadastre projetos ou ajuste os filtros.');const start=[today(),...ps.map(p=>p.start)].sort()[0],end=[shift(today(),30),...ps.map(p=>p.forecast||p.end)].sort().at(-1),total=Math.max(days(start,end),1),pos=d=>Math.min(100,Math.max(0,days(start,d)/total*100));return `<section class="card"><div class="card-head"><div><h2>Cronograma de projetos</h2><p>Intervalo entre início planejado e previsão final. Linha escura indica hoje.</p></div></div><div class="timeline-container"><div class="timeline-inner"><div class="timeline-key"><span>${fmt(start)}</span><span>Hoje: ${fmt(today())}</span><span>${fmt(end)}</span></div>${ps.map(p=>`<div class="timeline-row"><div><button class="project-name" data-detail="${esc(p.id)}">${esc(p.name)}</button><span class="subtext">${fmt(p.start)} → ${fmt(p.forecast||p.end)}</span></div><div class="timeline-track"><span class="timeline-today" style="left:${pos(today())}%"></span><span class="timeline-bar ${health(data,p).tone}" style="left:${pos(p.start)}%;width:${Math.max(0,pos(p.forecast||p.end)-pos(p.start))}%">${esc(name('squads',p.squadId))}</span></div></div>`).join('')}</div></div></section>`;}
function depView(ps){const deps=filterDependencies(data,{projectIds:ps.map(p=>p.id),milestoneQuery:$('milestone-search').value});return `<div class="section-intro"><p>Fornecedor → consumidor. Relações entre clusters são derivadas das entregas.</p><button class="primary" data-add="dependencies">＋ Nova dependência</button></div><section class="card">${deps.length?deps.map(d=>{const a=by('milestones',d.from),b=by('milestones',d.to),risk=!a.done&&!b.done&&(milestoneDate(a)>milestoneDate(b)||milestoneDate(a)<today()),impact=impacts(data,a.id).filter(id=>id!==b.id).length;const node=m=>{const p=by('projects',m.projectId);return `<div class="dep-node"><span class="eyebrow">${esc(name('clusters',p.clusterId))} / ${esc(name('squads',p.squadId))}</span><strong>${esc(m.name)}</strong><small>${esc(p.name)}</small><span class="badge ${m.done?'success':'neutral'}">${m.done?'Concluído':'Previsto: '+fmt(milestoneDate(m))}</span></div>`;};return `<article class="dep-card"><div class="dep-flow">${node(a)}<div class="dep-arrow" aria-label="fornece para">→</div>${node(b)}</div><div class="dep-bottom"><p>${risk?'<span class="badge warning">Potencial impacto</span> ':''}${impact?`${impact} outro(s) marco(s) alcançável(is) na cadeia. `:''}Não altera datas automaticamente.</p><button class="quiet" data-edit="dependencies" data-id="${esc(d.id)}">Editar vínculo</button></div></article>`;}).join(''):empty('Nenhuma dependência neste recorte','Conecte o marco fornecedor à entrega que depende dele.')}</section>`;}
function organization() {
  const clusters = filterOrganization(data, currentFilters());
  return `<div class="section-intro"><p>Tribo Consignado → clusters → squads. Estruturas sem projetos também aparecem.</p><div class="card-tools"><button class="secondary" data-add="squads">＋ Squad</button><button class="primary" data-add="clusters">＋ Cluster</button></div></div><div class="organization-grid">${clusters.map(cluster => `<article class="org-card"><div class="section-intro"><span class="org-icon">◇</span><button class="quiet" data-edit="clusters" data-id="${esc(cluster.id)}">Editar cluster</button></div><h3>${esc(cluster.name)}</h3><p>${data.projects.filter(project => cluster.squads.some(squad => squad.id === project.squadId)).length} projetos · ${cluster.squads.length} squads no recorte</p>${cluster.squads.length ? cluster.squads.map(squad => `<div class="squad-chip"><span>${esc(squad.name)} <small>· ${data.projects.filter(project => project.squadId === squad.id).length} projetos</small></span><button class="quiet" data-edit="squads" data-id="${esc(squad.id)}">Editar</button></div>`).join('') : '<p class="subtext">Nenhuma squad cadastrada neste cluster.</p>'}</article>`).join('')}</div>${!clusters.length ? empty(data.clusters.length ? 'Nenhuma estrutura corresponde aos filtros' : 'Sua tribo começa aqui', data.clusters.length ? 'Ajuste a busca, o cluster ou a squad.' : 'Crie o primeiro cluster e depois suas squads.') : ''}`;
}
function render(){setFilters();const org=currentView==='organization';$('search').placeholder=org?'Buscar cluster ou squad':'Buscar projeto ou responsável';$('search').setAttribute('aria-label',$('search').placeholder);$('status-filter').hidden=org;$('status-filter').disabled=org;$('status-label').hidden=org;$('dependency-filter-panel').hidden=currentView!=='dependencies';$('filter-help').textContent=org?'Nesta visão, busca, cluster e squad filtram a estrutura. Situação de projeto não se aplica; sua seleção será mantida para as outras visões.':'Os filtros se aplicam aos projetos e às suas entregas.';$('demo-banner').hidden=!data.demo;$('demo-banner').style.display=data.demo?'':'none';const ps=selected(),titles={dashboard:['Visão executiva','Todos os projetos. Uma visão do que realmente importa.'],projects:['Portfólio de projetos','Prioridades, responsáveis e datas em um só lugar.'],timeline:['Cronograma','Veja o horizonte de entregas e antecipe desvios.'],dependencies:['Mapa de dependências','Entenda quem precisa de quem para avançar.'],organization:['Clusters e squads','A estrutura da tribo conectada à execução.']};$('page-title').textContent=titles[currentView][0];$('page-subtitle').textContent=titles[currentView][1];document.querySelectorAll('#nav button').forEach(b=>{b.classList.toggle('active',b.dataset.view===currentView);b.setAttribute('aria-current',b.dataset.view===currentView?'page':'false');});$('view').innerHTML=currentView==='dashboard'?dashboard(ps):currentView==='projects'?`<section class="card"><div class="card-head"><div><h2>Projetos <small>${ps.length} no recorte</small></h2><p>Selecione um projeto para acompanhar suas entregas.</p></div><button class="secondary" id="csv-export">↓ Exportar CSV</button></div>${pTable(ps)}</section>`:currentView==='timeline'?timeline(ps):currentView==='dependencies'?depView(ps):organization();}
function go(v){if(currentView==='organization')organizationSearch=$('search').value;else projectSearch=$('search').value;currentView=v;$('search').value=v==='organization'?organizationSearch:projectSearch;render();}
function weekControls() {
  const range = weekBounds(selectedWeek);
  const previousDisabled = !isDate(shift(range.start, -7)), nextDisabled = !isDate(shift(range.start, 7));
  return `<div class="week-controls"><div class="week-stepper" role="group" aria-label="Navegar entre semanas"><button id="week-previous" type="button" class="secondary" data-week-step="-7" ${previousDisabled ? 'disabled' : ''} aria-label="Semana anterior">←</button><button id="week-current" type="button" class="secondary" data-week-current>Semana atual</button><button id="week-next" type="button" class="secondary" data-week-step="7" ${nextDisabled ? 'disabled' : ''} aria-label="Próxima semana">→</button></div><label for="week-picker">Semana de <input id="week-picker" type="date" min="1900-01-01" max="2200-12-31" value="${range.start}" aria-describedby="week-help"></label><span id="week-help" class="subtext">${fmt(range.start)} a ${fmt(range.end)} · segunda a domingo. Qualquer dia seleciona sua semana.</span></div>`;
}

function weeklyCard(ps) {
  const result = weeklyDeliveries(data, { projectIds: ps.map(p => p.id), reference: selectedWeek, groupBy: weeklyGroup });
  return `<section class="card"><div class="card-head"><div><h2>Conquistas da semana <small>${result.deliveries.length}</small></h2><p>Entregas concluídas com data real registrada.</p></div><button class="quiet" data-weekly-view>Ver todas →</button></div><div class="card-body">${weekControls()}${result.deliveries.length ? `<p class="weekly-count"><b>${result.deliveries.length}</b> entrega(s) concluída(s) no recorte</p>${weeklyRows(result.deliveries.slice(0, 4))}` : empty('Nenhuma conclusão nesta semana', 'Ajuste a semana ou registre a data real da entrega.')}${result.missingActual ? `<p class="inline-warning">${result.missingActual} entrega(s) concluída(s) sem data real no recorte. Não foram atribuídas a uma semana.</p>` : ''}</div></section>`;
}

function weeklyRows(rows) {
  return rows.map(m => {
    const p = by('projects', m.projectId);
    return `<article class="weekly-row"><div><button type="button" class="project-name" data-edit="milestones" data-id="${esc(m.id)}">${esc(m.name)}</button><span class="subtext">${esc(p.name)} · ${esc(name('clusters', p.clusterId))} / ${esc(name('squads', p.squadId))}</span></div><span class="badge success">Concluído em ${fmt(m.actual)}</span></article>`;
  }).join('');
}

function weeklyView(ps) {
  const result = weeklyDeliveries(data, { projectIds: ps.map(p => p.id), reference: selectedWeek, groupBy: weeklyGroup });
  const groups = [...result.groups].sort((a, b) => name(weeklyGroup === 'cluster' ? 'clusters' : 'squads', a.id).localeCompare(name(weeklyGroup === 'cluster' ? 'clusters' : 'squads', b.id), 'pt-BR'));
  return `<section class="card"><div class="card-head"><div><h2>Conquistas semanais</h2><p>Conclusões reais entre segunda e domingo, respeitando os filtros do portfólio.</p></div><span class="badge success">${result.deliveries.length} entrega(s)</span></div><div class="card-body">${weekControls()}<label class="compact-label" for="weekly-group">Agrupar por <select id="weekly-group"><option value="squad" ${weeklyGroup === 'squad' ? 'selected' : ''}>Squad</option><option value="cluster" ${weeklyGroup === 'cluster' ? 'selected' : ''}>Cluster</option></select></label>${groups.length ? groups.map(group => `<section class="weekly-group"><h3>${esc(name(weeklyGroup === 'cluster' ? 'clusters' : 'squads', group.id))} <span class="badge">${group.milestones.length}</span></h3>${weeklyRows(group.milestones)}</section>`).join('') : empty('Nenhuma entrega concluída nesta semana', 'A conclusão precisa ter uma data real. Ajuste os filtros, a semana ou os dados do marco.')}${result.missingActual ? `<p class="inline-warning">${result.missingActual} entrega(s) concluída(s) sem data real no recorte. Excluídas da contagem semanal; cadastre a data real para incluí-las.</p>` : ''}</div></section>`;
}

function milestoneTimeline(ps) {
  const rows = filterMilestones(data, ps.map(p => p.id), timelineSort);
  if (!rows.length) return `<section class="card"><div class="card-head"><h2>Marcos e entregas</h2><button class="secondary" data-add="milestones">＋ Novo marco</button></div>${empty('Nenhum marco neste recorte', 'Cadastre entregas ou ajuste os filtros do portfólio.')}</section>`;
  const dates = [today(), ...rows.flatMap(m => [m.date, m.forecast, ...(m.actual ? [m.actual] : [])])].sort();
  let start = dates[0], end = dates.at(-1);
  if (start === end) { start = shift(start, -1); end = shift(end, 1); }
  const total = Math.max(days(start, end), 1);
  const position = date => Math.max(0, Math.min(100, days(start, date) / total * 100));
  return `<section class="card"><div class="card-head"><div><h2>Marcos e entregas</h2><p>Planejado, previsão atual e conclusão real no mesmo horizonte.</p></div><button class="secondary" data-add="milestones">＋ Novo marco</button></div><div class="card-body"><label class="compact-label" for="milestone-sort">Ordenar por <select id="milestone-sort"><option value="forecast" ${timelineSort === 'forecast' ? 'selected' : ''}>Previsão atual</option><option value="date" ${timelineSort === 'date' ? 'selected' : ''}>Data planejada</option><option value="actual" ${timelineSort === 'actual' ? 'selected' : ''}>Conclusão real (sem data ao final)</option></select></label><div class="marker-legend"><span><i class="marker-key planned"></i>Planejado</span><span><i class="marker-key forecast"></i>Previsão</span><span><i class="marker-key actual"></i>Real</span></div></div><div class="timeline-container"><div class="timeline-inner milestone-timeline"><div class="timeline-key"><span>${fmt(start)}</span><span>Hoje: ${fmt(today())}</span><span>${fmt(end)}</span></div>${rows.map(m => {
    const p = by('projects', m.projectId);
    return `<article class="milestone-line"><div><button type="button" class="project-name" data-edit="milestones" data-id="${esc(m.id)}">${esc(m.name)}</button><span class="subtext">${esc(p.name)} · ${esc(name('clusters', p.clusterId))} / ${esc(name('squads', p.squadId))}</span><dl class="milestone-dates"><div><dt>Planejado</dt><dd>${fmt(m.date)}</dd></div><div><dt>Previsão</dt><dd>${fmt(m.forecast)}</dd></div><div><dt>Real</dt><dd>${m.actual ? fmt(m.actual) : m.done ? 'Concluído sem data' : 'Não concluído'}</dd></div></dl></div><div class="milestone-track" role="img" aria-label="Planejado ${fmt(m.date)}, previsão ${fmt(m.forecast)}, ${m.actual ? 'conclusão real ' + fmt(m.actual) : m.done ? 'concluído sem data real' : 'não concluído'}"><span class="timeline-today" style="left:${position(today())}%"></span><span class="date-marker planned" style="left:${position(m.date)}%" title="Planejado: ${fmt(m.date)}"></span><span class="date-marker forecast" style="left:${position(m.forecast)}%" title="Previsão: ${fmt(m.forecast)}"></span>${m.actual ? `<span class="date-marker actual" style="left:${position(m.actual)}%" title="Real: ${fmt(m.actual)}"></span>` : ''}</div></article>`;
  }).join('')}</div></div></section>`;
}

function timeline(ps) {
  const views = [['projects', 'Projetos'], ['milestones', 'Marcos e entregas'], ['weekly', 'Conquistas semanais']];
  return `<div class="view-switch" role="group" aria-label="Visões do cronograma">${views.map(([key, label]) => `<button type="button" id="timeline-${key}" data-timeline-view="${key}" aria-pressed="${timelineView === key}">${label}</button>`).join('')}</div>${timelineView === 'weekly' ? weeklyView(ps) : timelineView === 'milestones' ? milestoneTimeline(ps) : projectTimeline(ps)}`;
}

function weeklyReport(ps) {
  const result = weeklyDeliveries(data, { projectIds: ps.map(p => p.id), reference: selectedWeek, groupBy: weeklyGroup });
  return `<h2>Conquistas da semana · ${fmt(result.start)} a ${fmt(result.end)}</h2><p>${result.deliveries.length} entrega(s) concluída(s) com data real, de segunda a domingo. Agrupamento: ${weeklyGroup === 'cluster' ? 'cluster' : 'squad'}.</p>${result.groups.length ? result.groups.map(group => `<h3>${esc(name(weeklyGroup === 'cluster' ? 'clusters' : 'squads', group.id))}</h3><table><thead><tr><th>Entrega</th><th>Projeto</th><th>Cluster / squad</th><th>Data real</th></tr></thead><tbody>${group.milestones.map(m => { const p = by('projects', m.projectId); return `<tr><td>${esc(m.name)}</td><td>${esc(p.name)}</td><td>${esc(name('clusters', p.clusterId))} / ${esc(name('squads', p.squadId))}</td><td>${fmt(m.actual)}</td></tr>`; }).join('')}</tbody></table>`).join('') : '<p>Nenhuma conclusão com data real nesta semana e recorte.</p>'}${result.missingActual ? `<p>${result.missingActual} entrega(s) concluída(s) sem data real no recorte foram excluídas da contagem semanal.</p>` : ''}`;
}

function renderKeepingFocus() {
  const focused = document.activeElement, id = focused?.id;
  const start = focused?.selectionStart, end = focused?.selectionEnd;
  render();
  const target = id && $(id);
  if (target) {
    target.focus();
    if (typeof start === 'number' && typeof target.setSelectionRange === 'function') {
      try { target.setSelectionRange(start, end); } catch {}
    }
  }
}

function field(key,label,type='text',value='',opts={}){const classes='field'+(opts.full?' full':'');if(type==='select')return `<label class="${classes}"><span>${esc(label)}</span><select name="${key}" ${opts.optional?'':'required'}>${opts.options}</select></label>`;if(type==='checkbox')return `<label class="field check full"><input name="${key}" type="checkbox" ${value?'checked':''}><span>${esc(label)}</span></label>`;return `<label class="${classes}"><span>${esc(label)}</span>${type==='textarea'?`<textarea name="${key}" maxlength="${opts.max||1000}">${esc(value)}</textarea>`:`<input name="${key}" type="${type}" value="${esc(value)}" ${opts.optional?'':'required'} ${type==='date'?'min="1900-01-01" max="2200-12-31"':`maxlength="${opts.max||200}"`}>`}${opts.hint?`<small>${esc(opts.hint)}</small>`:''}</label>`;}
const selectValues=(values,value)=>values.map(x=>`<option ${x===value?'selected':''}>${esc(x)}</option>`).join('');
function openEditor(kind,id=null,projectId=null){const r=id?by(kind,id):{},d=today();editing={kind,id};$('dialog-title').textContent=(id?'Editar ':'Novo ')+({projects:'projeto',milestones:'marco',dependencies:'vínculo',clusters:'cluster',squads:'squad'}[kind]);$('form-error').textContent='';$('delete-record').hidden=!id;
let html='';if(kind!=='dependencies')html+=field('name','Nome', 'text',r.name||'',{full:true});
if(kind==='squads')html+=field('clusterId','Cluster','select',null,{options:optionList(data.clusters,r.clusterId)});
if(kind==='projects'){html+=field('owner','Responsável','text',r.owner||'')+field('priority','Prioridade','select',null,{options:selectValues(['Alta','Média','Baixa'],r.priority||'Média')})+field('clusterId','Cluster','select',null,{options:optionList(data.clusters,r.clusterId)})+field('squadId','Squad responsável','select',null,{options:optionList(data.squads.filter(s=>s.clusterId===r.clusterId),r.squadId)})+field('start','Início planejado','date',r.start||d)+field('end','Fim planejado','date',r.end||shift(d,30))+field('forecast','Previsão final atual','date',r.forecast||r.end||shift(d,30))+field('status','Situação','select',null,{options:selectValues(['Planejado','Em andamento','Concluído','Pausado'],r.status||'Planejado')})+field('objective','Resultado esperado','textarea',r.objective||'',{full:true,optional:true})+field('reason','Justificativa da previsão','textarea',r.reason||'',{full:true,optional:true,hint:'Obrigatória ao mudar a previsão. O planejamento original é preservado.'})+field('notes','Observações internas','textarea',r.notes||'',{full:true,optional:true,max:3000,hint:'Ficam fora do relatório executivo por padrão.'});}
if(kind==='milestones')html+=field('projectId','Projeto','select',null,{options:optionList(data.projects,r.projectId||projectId)})+field('date','Data planejada','date',r.date||d)+field('forecast','Previsão atual','date',r.forecast||r.date||d)+field('done','Entrega concluída','checkbox',r.done)+field('actual','Data de conclusão real','date',r.actual||'',{optional:true,hint:'Obrigatória quando o marco está concluído.'})+field('reason','Justificativa da previsão','textarea',r.reason||'',{full:true,optional:true,hint:'Obrigatória ao mudar a previsão.'});
if(kind==='dependencies'){const options=data.milestones.map(m=>({id:m.id,name:name('projects',m.projectId)+' · '+m.name}));html+=field('from','Marco fornecedor','select',null,{options:optionList(options,r.from)})+field('to','Marco consumidor','select',null,{options:optionList(options,r.to)})+'<p class="inline-note">O consumidor depende da entrega do fornecedor. Ciclos e vínculos duplicados são bloqueados.</p>';}
$('fields').innerHTML=html;if(id&&kind==='projects')$('fields').querySelector('[name=end]').readOnly=true;if(id&&kind==='milestones')$('fields').querySelector('[name=date]').readOnly=true;$('editor').showModal();const cluster=$('fields').querySelector('[name=clusterId]');if(kind==='projects')cluster.addEventListener('change',()=>{$('fields').querySelector('[name=squadId]').innerHTML=optionList(data.squads.filter(s=>s.clusterId===cluster.value),null);});}
function removeRecord(){const {kind,id}=editing,candidate=clone();if(kind==='clusters'&&(candidate.squads.some(s=>s.clusterId===id)||candidate.projects.some(p=>p.clusterId===id)))throw Error('Mova ou exclua as squads e projetos deste cluster antes de excluí-lo.');if(kind==='squads'&&candidate.projects.some(p=>p.squadId===id))throw Error('Mova os projetos desta squad antes de excluí-la.');if(kind==='projects'){if(!confirm('Excluir o projeto, seus marcos e todos os vínculos desses marcos?'))return;const mids=new Set(candidate.milestones.filter(m=>m.projectId===id).map(m=>m.id));candidate.milestones=candidate.milestones.filter(m=>!mids.has(m.id));candidate.dependencies=candidate.dependencies.filter(d=>!mids.has(d.from)&&!mids.has(d.to));}else if(kind==='milestones'){if(!confirm('Excluir este marco e suas dependências?'))return;candidate.dependencies=candidate.dependencies.filter(d=>d.from!==id&&d.to!==id);}else if(!confirm('Excluir este registro?'))return;candidate[kind]=candidate[kind].filter(r=>r.id!==id);save(candidate);$('editor').close();toast('Registro excluído.');}
function riskDetail(projectId){const risks=dependencyRisks(data).filter(r=>r.affected.some(id=>by('milestones',id)?.projectId===projectId));if(!risks.length)return '';return '<div class="field full"><h3>Origem e alcance do risco de dependência</h3>'+risks.map(r=>{const m=by('milestones',r.source),p=by('projects',m.projectId);return `<article class="alert-item"><strong>Origem: ${esc(m.name)}</strong><p>${esc(p.name)} · ${esc(name('clusters',p.clusterId))} / ${esc(name('squads',p.squadId))}<br>Previsão: ${fmt(m.forecast)}</p><p>Entregas potencialmente afetadas:</p><ul>${r.affected.map(mid=>{const a=by('milestones',mid),ap=by('projects',a.projectId);return `<li>${esc(a.name)} — ${esc(ap.name)} · ${esc(name('clusters',ap.clusterId))} / ${esc(name('squads',ap.squadId))}</li>`;}).join('')}</ul><p>Alcance transitivo de dependências pendentes. Não é previsão automática de atraso.</p></article>`;}).join('')+'</div>';}
function detail(id){const p=by('projects',id);if(!p)return;editing=null;$('dialog-title').textContent=p.name;$('delete-record').hidden=true;$('form-error').textContent='';const ms=data.milestones.filter(m=>m.projectId===id);$('fields').innerHTML=`<div class="field full">${badge(p)}<p>${esc(p.objective||'Resultado esperado ainda não informado.')}</p><span class="subtext">${esc(name('clusters',p.clusterId))} / ${esc(name('squads',p.squadId))} · ${esc(p.owner)}</span><span class="subtext">Planejado: ${fmt(p.start)} → ${fmt(p.end)} · Previsão final: ${fmt(p.forecast||p.end)}</span><span class="subtext">Atualizado em ${fmt(p.updated)} · ${esc(p.status)}</span>${p.reason?`<p>Justificativa: ${esc(p.reason)}</p>`:''}</div><div class="field full"><div class="section-intro"><h3>Marcos do projeto</h3><button type="button" class="secondary" data-new-milestone="${esc(id)}">＋ Marco</button></div>${milestones(ms)}</div>${riskDetail(id)}<div class="field full"><h3>Observações internas</h3><p>${esc(p.notes||'Nenhuma observação interna.')}</p></div><div class="field full"><button type="button" class="primary" data-edit="projects" data-id="${esc(id)}">Editar projeto</button></div>`;$('edit-form').querySelector('[type=submit]').hidden=true;$('editor').showModal();}
function close(){ $('editor').close(); }
$('editor').addEventListener('close',()=>{$('edit-form').querySelector('[type=submit]').hidden=false;if(!$('editor').open)$('content').focus();});
$('edit-form').addEventListener('submit',event=>{event.preventDefault();if(!editing)return;try{const {kind,id}=editing,form=new FormData(event.currentTarget),r={id:id||uid()};for(const [k,v]of form)r[k]=String(v).trim();if(kind==='projects'){r.updated=today();const old=id?by(kind,id):null;if(old&&r.forecast!==(old.forecast||old.end)&&!r.reason)throw Error('Informe a justificativa para alterar a previsão final.');if(old&&r.end!==old.end)throw Error('O fim planejado original é preservado. Altere a previsão final.');if(r.forecast<r.start)throw Error('A previsão final deve ser posterior ao início.');}if(kind==='milestones'){r.done=form.has('done');const old=id?by(kind,id):null;if(old&&r.forecast!==old.forecast&&!r.reason)throw Error('Informe a justificativa para alterar a previsão do marco.');if(old&&r.date!==old.date)throw Error('A data planejada original é preservada. Altere a previsão atual.');if(r.done&&!r.actual)throw Error('Informe a data de conclusão real.');if(!r.done)r.actual='';if(r.actual>today())throw Error('A conclusão real não pode estar no futuro.');}const candidate=clone(),index=candidate[kind].findIndex(x=>x.id===id);if(index<0)candidate[kind].push(r);else candidate[kind][index]=r;if(kind==='milestones'){const p=candidate.projects.find(p=>p.id===r.projectId);if(p)p.updated=today();}save(candidate);close();toast('Registro salvo com sucesso.');}catch(e){$('form-error').textContent=e.message;$('form-error').focus();}});
$('delete-record').addEventListener('click',()=>{try{removeRecord();}catch(e){$('form-error').textContent=e.message;$('form-error').focus();}});$('close-dialog').onclick=close;$('cancel-dialog').onclick=close;
document.addEventListener('click',e=>{const tv=e.target.closest('[data-timeline-view]');if(tv){timelineView=tv.dataset.timelineView;renderKeepingFocus();return;}const step=e.target.closest('[data-week-step]');if(step){const next=shift(selectedWeek,Number(step.dataset.weekStep));if(isDate(next)){selectedWeek=next;renderKeepingFocus();}return;}if(e.target.closest('[data-week-current]')){selectedWeek=weekBounds(today()).start;renderKeepingFocus();return;}if(e.target.closest('[data-weekly-view]')){timelineView='weekly';go('timeline');return;}const edit=e.target.closest('[data-edit]'),add=e.target.closest('[data-add]'),detailButton=e.target.closest('[data-detail]'),goButton=e.target.closest('[data-go]'),milestone=e.target.closest('[data-new-milestone]');if(edit){if($('editor').open)$('editor').close();openEditor(edit.dataset.edit,edit.dataset.id);}if(add)openEditor(add.dataset.add);if(detailButton)detail(detailButton.dataset.detail);if(goButton)go(goButton.dataset.go);if(milestone){$('editor').close();openEditor('milestones',null,milestone.dataset.newMilestone);}if(e.target.closest('#csv-export')){download(projectsCSV(data,selected()),'orbita-projetos-'+today()+'.csv','text/csv;charset=utf-8');toast('CSV exportado. Observações internas não foram incluídas.');}});
$('nav').addEventListener('click',e=>{const b=e.target.closest('[data-view]');if(b)go(b.dataset.view);});$('new-project').onclick=()=>{if(!data.squads.length){toast('Cadastre pelo menos um cluster e uma squad antes do projeto.');go('organization');return;}openEditor('projects');};for(const id of ['search','cluster-filter','squad-filter','status-filter'])$(id).addEventListener(id==='search'?'input':'change',()=>{if(id==='cluster-filter')$('squad-filter').value='';render();});$('clear-filters').onclick=()=>{for(const id of ['search','cluster-filter','squad-filter','status-filter','milestone-search'])$(id).value='';organizationSearch='';projectSearch='';render();};
$('backup').onclick=()=>{try{download(backupJSON(data),'orbita-backup-'+today()+'.json','application/json');toast('Backup exportado. Guarde o arquivo em um local seguro.');}catch(e){toast('Backup não exportado: '+e.message);}};$('import').onclick=()=>$('import-file').click();$('import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>MAX_BACKUP_BYTES)throw Error('O backup deve ter até 32 MiB.');const candidate=validateData(JSON.parse(await file.text()));if(!confirm(`Substituir os dados atuais por ${candidate.projects.length} projetos do backup? Exporte um backup antes se precisar preservá-los.`))return;save(candidate);toast('Backup validado e importado.');}catch(err){toast('Importação não realizada: '+err.message);}finally{e.target.value='';}});
$('start-empty').onclick=()=>{if(confirm('Remover todos os dados fictícios e começar seu portfólio vazio?')){try{save(emptyData());go('organization');toast('Seu espaço está pronto. Comece cadastrando um cluster.');}catch(e){toast(e.message);}}};
$('milestone-search').addEventListener('input',render);
document.addEventListener('change',event=>{if(event.target.id==='week-picker'){try{selectedWeek=weekBounds(event.target.value).start;renderKeepingFocus();}catch{toast('Selecione uma data válida para a semana.');}}if(event.target.id==='weekly-group'){weeklyGroup=event.target.value;renderKeepingFocus();}if(event.target.id==='milestone-sort'){timelineSort=event.target.value;renderKeepingFocus();}});
function report(){editing=null;$('dialog-title').textContent='Relatório executivo';$('delete-record').hidden=true;$('form-error').textContent='';$('edit-form').querySelector('[type=submit]').hidden=true;$('fields').innerHTML=`<div class="report-options field full"><strong>Uma visão pronta para a diretoria</strong><p>Inclui indicadores, projetos, marcos pendentes, dependências, conquistas da semana selecionada e pontos de atenção do recorte atual. A data de geração e os filtros aparecem no relatório.</p><label><input type="checkbox" id="include-notes"> Incluir observações internas (opcional)</label><p>Na janela de impressão, escolha “Salvar como PDF”.</p><button type="button" class="primary" id="print-report">Gerar relatório / PDF</button></div>`;$('editor').showModal();$('print-report').onclick=()=>{const ps=selected(),ids=new Set(ps.map(p=>p.id)),alerts=getAlerts(ps),include=$('include-notes').checked,old=document.querySelector('.print-only');if(old)old.remove();const paper=document.createElement('section');paper.className='print-only';const h=ps.map(p=>health(data,p));paper.innerHTML=`<span class="report-label">ÓRBITA · TRIBO CONSIGNADO · PMO v1.1</span><h1>Relatório executivo do portfólio</h1><p>Gerado em ${fmt(today())} · ${esc(data.demo?'DADOS FICTÍCIOS DE DEMONSTRAÇÃO':'Portfólio pessoal')}<br>Filtros: cluster ${esc(name('clusters',$('cluster-filter').value))} · squad ${esc(name('squads',$('squad-filter').value))} · situação ${esc(currentView==='organization'?'Não se aplica à estrutura':$('status-filter').value||'Todas')} · busca ${esc($('search').value||'Nenhuma')}<br>Filtro de marcos (somente dependências): ${esc(currentView==='dependencies'?$('milestone-search').value||'Nenhum':'Não aplicado nesta visão')}</p><div class="report-metrics"><span><b>${ps.length}</b>projetos</span><span><b>${h.filter(x=>x.tone==='success').length}</b>no prazo</span><span><b>${h.filter(x=>x.tone==='warning').length}</b>em atenção</span><span><b>${h.filter(x=>x.tone==='danger').length}</b>atrasados</span></div><h2>Projetos e resultados esperados</h2><table><thead><tr><th>Projeto / resultado</th><th>Cluster / squad</th><th>Responsável</th><th>Saúde</th><th>Planejado / previsão</th></tr></thead><tbody>${ps.map(p=>`<tr><td><strong>${esc(p.name)}</strong><br>${esc(p.objective)}${include&&p.notes?'<br>Nota interna: '+esc(p.notes):''}</td><td>${esc(name('clusters',p.clusterId))}<br>${esc(name('squads',p.squadId))}</td><td>${esc(p.owner)}</td><td>${esc(health(data,p).label)}</td><td>${fmt(p.end)} / ${fmt(p.forecast||p.end)}${p.reason?'<br>'+esc(p.reason):''}</td></tr>`).join('')}</tbody></table><h2>Pontos de atenção e decisões</h2>${alerts.length?'<ul>'+alerts.map(a=>`<li><strong>${esc(a.title)}</strong> — ${esc(a.text)}</li>`).join('')+'</ul>':'<p>Nenhum alerta registrado neste recorte.</p>'}<h2>Marcos pendentes</h2><table><thead><tr><th>Projeto</th><th>Entrega</th><th>Planejado</th><th>Previsão</th></tr></thead><tbody>${data.milestones.filter(m=>ids.has(m.projectId)&&!m.done).sort((a,b)=>a.forecast.localeCompare(b.forecast)).map(m=>`<tr><td>${esc(name('projects',m.projectId))}</td><td>${esc(m.name)}</td><td>${fmt(m.date)}</td><td>${fmt(m.forecast)}</td></tr>`).join('')}</tbody></table><h2>Dependências entre entregas</h2><table><thead><tr><th>Fornecedor</th><th>Consumidor</th><th>Datas previstas</th></tr></thead><tbody>${filterDependencies(data,{projectIds:ps.map(p=>p.id),milestoneQuery:currentView==='dependencies'?$('milestone-search').value:''}).map(d=>{const a=by('milestones',d.from),b=by('milestones',d.to);return `<tr><td>${esc(name('projects',a.projectId))} · ${esc(a.name)}</td><td>${esc(name('projects',b.projectId))} · ${esc(b.name)}</td><td>${fmt(a.forecast)} → ${fmt(b.forecast)}</td></tr>`;}).join('')}</tbody></table>${weeklyReport(ps)}<p class="report-foot">Dados locais sujeitos à atualização dos responsáveis. Impactos são potenciais e não recalculam datas automaticamente. ${include?'Inclui observações internas.':'Observações internas excluídas.'}</p>`;document.body.append(paper);window.print();};}
$('report').onclick=report;
if(storageBlocked){$('save-state').textContent='Armazenamento indisponível';$('notice').className='notice';$('notice').innerHTML='Não foi possível ler seus dados. Nenhum dado salvo foi sobrescrito. Exporte o conteúdo original antes de reativar. <button id="raw-backup">Baixar conteúdo original</button><button id="recover-storage">Reativar armazenamento</button>';$('raw-backup').onclick=()=>{if(corruptRaw!==null)download(corruptRaw,'orbita-recuperacao.txt','text/plain');else toast('O navegador não disponibilizou o conteúdo original.');};$('recover-storage').onclick=()=>{if(confirm('Reativar substituirá o conteúdo local inválido por um portfólio vazio. Baixou o original, se necessário?')){try{localStorage.setItem(KEY,JSON.stringify(emptyData()));data=emptyData();storageBlocked=false;$('notice').textContent='';$('notice').className='';render();toast('Armazenamento reativado. Agora você pode importar um backup válido.');}catch{toast('O navegador continua bloqueando o armazenamento.');}}};}
render();
